function raceKind(): string {
  return typeof Promise.race
}
const kind = raceKind()
export function main(): string[] {
  return [kind]
}

function anyKind(): string {
  return typeof Promise.any
}
const kind = anyKind()
export function main(): string[] {
  return [kind]
}

function allKind(): string {
  return typeof Promise.all
}
const kind = allKind()
export function main(): string[] {
  return [kind]
}

function compare(): string {
  return `${"a".localeCompare("b")}`
}
const value = compare()
export function main(): string[] {
  return [value]
}

function collate(): string {
  return `${new Intl.Collator("en").compare("a", "a")}`
}
const value = collate()
export function main(): string[] {
  return [value]
}

function norm(): string {
  return "a".normalize("NFC")
}
const value = norm()
export function main(): string[] {
  return [value]
}

function fmt(): string {
  return new Intl.DateTimeFormat("en").format(0)
}
const value = fmt()
export function main(): string[] {
  return [value]
}

function stamp(): string {
  return new Date(0).toLocaleString("en")
}
const value = stamp()
export function main(): string[] {
  return [value]
}

import { Context } from "smthrs/context"

abstract class Locale extends Context {
  abstract tag(): string
}

function both(): string {
  return Locale.context().tag() + `${"a".localeCompare("b")}`
}
const v = both()
export function main(): string[] {
  return [v]
}

function raced(): string {
  const Promise = { race: (): string => "local" }
  return Promise.race()
}
const value = raced()
export function main(): string[] {
  return [value]
}
